% Units used in createSensors and createDrivingScenario
% Distance/Position - meters
% Speed             - meters/second
% Angles            - degrees
% RCS Pattern       - dBsm

function [sensors, numSensors] = createSensors(scnro)
% createSensors Returns all sensor objects to generate detections

% Assign into each sensor the physical and radar profiles for all actors
profiles = actorProfiles(scnro);
sensors{1} = visionDetectionGenerator(SensorIndex = 1, ...
    SensorLocation = [2 0], ...
    MaxRange = 100, ...
    DetectorOutput = 'Objects only', ...
    Intrinsics = cameraIntrinsics([1814.81018227767 1814.81018227767],[320 240],[480 640]), ...
    ActorProfiles = profiles);
sensors{2} = drivingRadarDataGenerator(SensorIndex = 2, ...
    MountingLocation = [1.974 -0.75 0.2], ...
    MountingAngles = [-90 0 0], ...
    TargetReportFormat = 'Detections', ...
    Profiles = profiles);
sensors{3} = drivingRadarDataGenerator(SensorIndex = 3, ...
    MountingLocation = [1.927 0.75 0.2], ...
    MountingAngles = [90 0 0], ...
    TargetReportFormat = 'Detections', ...
    Profiles = profiles);
sensors{4} = lidarPointCloudGenerator(SensorIndex = 4, ...
    SensorLocation = [0.467 -0.01], ...
    ActorProfiles = profiles);
sensors{5} = insSensor(TimeInput = true);
sensors{6} = ultrasonicDetectionGenerator(SensorIndex = 6, ...
    MountingLocation = [1.993 0.734 0.2], ...
    Profiles = profiles);
sensors{7} = ultrasonicDetectionGenerator(SensorIndex = 7, ...
    MountingLocation = [1.987 -0.726 0.2], ...
    Profiles = profiles);
sensors{8} = ultrasonicDetectionGenerator(SensorIndex = 8, ...
    MountingLocation = [0 0.75 0.2], ...
    MountingAngles = [91.5154079000221 0 0], ...
    Profiles = profiles);
sensors{9} = ultrasonicDetectionGenerator(SensorIndex = 9, ...
    MountingLocation = [0 -0.75 0.2], ...
    MountingAngles = [-90 0 0], ...
    Profiles = profiles);
numSensors = 9;

function [scnro, egoVehicle] = createDrivingScenario
% createDrivingScenario Returns the drivingScenario defined in the Designer

% Construct a drivingScenario object.
scnro = drivingScenario;

% Add all road segments
roadCenters = [53.3 -0.7 0;
    -4.7 -0.5 0];
laneSpecification = lanespec(3);
road(scnro, roadCenters, Lanes = laneSpecification, Name = 'Road');

% Add the ego vehicle
egoVehicle = vehicle(scnro, ...
    ClassID = 1, ...
    Length = 3, ...
    Width = 1.5, ...
    Height = 2, ...
    Position = [1.11 0.21 0.01], ...
    RearOverhang = 1, ...
    FrontOverhang = 0.9, ...
    Mesh = driving.scenario.carMesh, ...
    Name = 'Car');
waypoints = [1.11 0.21 0.01;
    5.52 0.16 0.01;
    12.51 -0.9 0.01;
    20.05 -2.25 0.01;
    27.9 -3.8 0;
    37.2 -4.3 0;
    46.3 -4.3 0;
    52.9 -3.8 0];
speed = [0;20;30;35;33;30;15;0];
yaw =  [0;0;0;0;0;0;0;0];
trajectory(egoVehicle, waypoints, speed, Yaw = yaw);

% Add the non-ego actors
car1 = vehicle(scnro, ...
    ClassID = 1, ...
    Position = [18.34 3.25 0], ...
    Mesh = driving.scenario.carMesh, ...
    PlotColor = [1 0.909 0.392], ...
    Name = 'Car1');
waypoints = [18.34 3.25 0;
    19.1 3.1 0;
    32.4 1.2 0;
    42.8 -0.1 0;
    51 -0.2 0;
    52.8 -0.15 0];
speed = [0;15;25;15;5;0];
yaw =  [0;0;0;0;0;0];
trajectory(car1, waypoints, speed, Yaw = yaw);

car2 = vehicle(scnro, ...
    ClassID = 1, ...
    Position = [4.34076741103418 3.34057965555113 0], ...
    Mesh = driving.scenario.carMesh, ...
    PlotColor = [0.752 0.36 0.984], ...
    Name = 'Car2');
waypoints = [4.34076741103418 3.34057965555113 0;
    16.8 3.2 0;
    31.3 3.2 0;
    43.8 3.2 0;
    49.1 3.2 0;
    52.4 3.2 0];
speed = [0;20;30;25;15;0];
yaw =  [0;0;NaN;NaN;NaN;NaN];
trajectory(car2, waypoints, speed, Yaw = yaw);

% Display the scenario
% plot(scnro,Waypoints = "on");
% while advance(scnro)
%    pause(scnro.SampleTime);
% end

function output = getDetectorOutput(sensor)

if isa(sensor, 'visionDetectionGenerator')
    output = sensor.DetectorOutput;
elseif isa(sensor, 'lidarPointCloudGenerator')
    output = 'PointCloud';
elseif isa(sensor, 'insSensor')
    output = 'INSMeasurement';
else
    output = 'Objects only';
end

